import os, sys, re, json, collections
sys.stdout.reconfigure(encoding='utf-8')
R = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
g = json.load(open(R + '/work/review/raw.json', encoding='utf-8'))
def sp(jp): m = re.match(r'\[([^\]]*)\]', jp); return m.group(1) if m else ''
# 호칭 토큰 → 번역에서 나온 후보
C = {'おばさん': '이모|고모|숙모|아주머니|아줌마|여주인|누님', 'おばさま|伯母|叔母|おば様': '이모|고모|숙모|아주머니|백모|외숙모', '逍遥さん': '소요 오빠|소요 씨|소요님|오빠|소요 공자|소요', '逍遥兄さん': '소요 오빠|소요 형|오빠|형',
 '李さん': '이 씨|이씨|이 오빠|이 형|이소요 씨|소요|이 공자|이 소협|오빠', '李兄さん': '이 형|이 오빠|이 형님|형님|형', '劉兄さん': '유 형|유 형님|형님|형', '霊児': '조영아|조령아|영아|령아', '林お嬢|林さん': '임 아가씨|임 낭자|임 소저|월여|임 씨',
 '月如': '월여|월이', '趙さん|趙お嬢': '조 아가씨|조 낭자|조 소저|영아|조 씨', 'お嬢さん': '아가씨|낭자|소저|아씨', 'ばあや': '할멈|유모|할머니|할머님', '師匠': '사부|스승', '剣の聖人': '검성|검의 성인', '酒飲み剣士': '술꾼 검사|술꾼 검객', 'お鈴': '아노|오린|아령|방울', 'お彩': '오채|채아|채',
 '長官': '장관|현령|부윤', '若旦那': '도련님|젊은 나리|작은 주인', '奥様': '마님|부인|아씨', '巫后': '무후', '女咼': '여와|여와낭랑', '拝月教': '배월교', '南詔': '남조', '苗彊|苗疆': '묘강', '大理': '대리', '揚州': '양주', '蘇州': '소주', '余杭': '여항', '長安': '장안', '蜀山': '촉산', '仙霊島': '선령도|선영도', '水月宮': '수월궁', '白河': '백하', '黒水鎮|黒水': '흑수진|흑수', '聖霊': '성령|성영', '霊珠': '영주|령주', '文銭': '문전|문', '両': '냥|량', '仙術': '선술', '術法|術': '술법|법술|방술|술', '江湖': '강호', '武林': '무림', '茅山': '모산', '桃源': '도원', '御剣': '어검|검을 타', '女将': '여주인|안주인|주모', '小僧': '꼬마|녀석|놈|소승|자식', 'しかばね|屍': '시체|강시|주검', 'ゾンビ|キョンシー': '강시|좀비', '盗侠': '도협|도둑 협객|의적','南の盗侠':'남도협','女媧':'여와','太古':'태고'}
for t, cand in C.items():
    rx = re.compile(t); cs = sorted(cand.split('|'), key=len, reverse=True); cnt = collections.Counter(); ex = collections.defaultdict(list); bysp = collections.defaultdict(collections.Counter)
    for k, v in g.items():
        if k[0] != 'T': continue
        j = re.sub(r'^\[[^\]]*\]', '', v[3]).replace('／　', '').replace('／', ''); o = re.sub(r'^\[[^\]]*\]', '', v[4]).replace('／', ' ')
        o1 = o.replace(' ', '')
        if rx.search(j):
            h = next((c for c in cs if c in o or c.replace(' ', '') in o1), '?'); cnt[h] += 1; ex[h].append(k); bysp[sp(v[3])][h] += 1
    print(t, dict(cnt.most_common()), '| ?', ex['?'][:8])
